namespace resources.icons;






/**
 * <code>IconWrapper</code> provides a simple icon wrapper which 
 * delays icon construction until its first use.
 */
public abstract class IconWrapper : Icon {

	private Icon icon;

	/**
	 * Creates the icon upon first use.
	 * @return icon
	 */
	protected abstract Icon createIcon();

	private void init() {
		if (icon == null) {
			icon = createIcon();
		}
	}

	/* @Override */
	public int getIconHeight() {
		init();
		return icon.getIconHeight();
	}

	/* @Override */
	public int getIconWidth() {
		init();
		return icon.getIconWidth();
	}

	/* @Override */
	public void paintIcon(Component c, Graphics g, int x, int y) {
		init();
		icon.paintIcon(c, g, x, y);
	}

}
